        const ra = Math.max(0, raRaw - testOaTransfer);
        const stdM = Math.round(interpolateCpfLife(ra, 'std', isMalePdf, testPA));
        const escM = Math.round(interpolateCpfLife(ra, 'esc', isMalePdf, testPA));
